//! DATA-to-journal-to-HTTP writer proof, not acceptance of peer iteration.
//! The first consented round has no child outcomes yet. B1 separately proves
//! exact pending-child evidence. All profiles/endpoints/results are synthetic.
use super::*;
use crate::pet_runtime::{peer_round_data::Captured,peer_round_review::{Review as DataReview,Approved,Observe},delegation_api::DelegationInput,planned_peer_tests::hybrid_delegation as hybrid,planning_journal,planning,recipe_decisions::Source,authority_store::Fault};
fn config(provider:&str)->crate::pet_config::Configuration{let mut c=crate::pet_config::defaults();c.pets.get_mut(crate::pet_config::pet_id(provider).unwrap()).unwrap().provider=provider.into();c}
fn owned_at(server:&crate::local_chat::Server)->(Fixture,Authority,Record,Arc<Owned>,Chat){
 owned_at_with_fence(server,Arc::new(|_,_,_|Validity::Current))
}
fn owned_at_with_fence(server:&crate::local_chat::Server,fence:Fence)->(Fixture,Authority,Record,Arc<Owned>,Chat){
 let provider=server.id;hybrid::own_with_evidence_fence(provider,hybrid::cap(),|g,at|{
  let mut descriptor=crate::pet_runtime::admission_tests::descriptor(g,at);
  if provider=="lmstudio"{descriptor.binding.engine_binding=Some(crate::local_chat::lmstudio::Catalog::parse(server,&json!({"models":[{"type":"llm","key":"fixture-free","publisher":"private-fixture","format":"gguf","size_bytes":1,"loaded_instances":[]}]})).unwrap().binding("fixture-free").unwrap());}
  crate::pet_runtime::admission::Evidence::observe(g,&descriptor,"a".repeat(64),at,false,false).unwrap()
 },fence)
}
#[test]fn expired_model_readiness_allows_exact_data_preparation_but_never_effects_or_revoked_policy(){
 for provider in ["ollama","lmstudio"]{
  let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let server=crate::local_chat::Server{id:provider,name:"No IO from passive DATA preparation",url:format!("http://{}",listener.local_addr().unwrap()),key:None};
  let fresh=Arc::new(AtomicBool::new(true));let policy=Arc::new(AtomicBool::new(true));let f=fresh.clone();let p=policy.clone();let fence:Fence=Arc::new(move|_,_,mode|if !p.load(Ordering::Acquire){Validity::Changed}else if mode==Validation::FreshEffect&&!f.load(Ordering::Acquire){Validity::Unknown}else{Validity::Current});
  let(f,a,g,o,_main)=owned_at_with_fence(&server,fence);let before=grant(&f,&g);fresh.store(false,Ordering::Release);assert!(!o.current(crate::assistant_memory::now()));
  let round=o.prepare_peer_round(&g,&server,"passive-data-after-wait",data_for(&f,&g,&o,&server),&config(provider)).unwrap();let review=round.review();let url=server.url.clone();let observe:Observe=Arc::new(move||Ok((config(provider),crate::local_chat::Server{id:provider,name:"Same reviewed destination",url:url.clone(),key:None})));
  let source=Source::capture_peer_data(o.clone(),&g,review.clone(),Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap()),observe.clone()).unwrap();let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=Arc::new(review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap());
  assert!(o.consume_actual_call_with_peer_data(&g,"passive-data-after-wait",round.prepared,Some(approved),crate::assistant_memory::now()).is_err());assert_eq!(o.workers(),0);assert_eq!(grant(&f,&g),before);assert!(listener.accept().is_err());
  policy.store(false,Ordering::Release);fresh.store(true,Ordering::Release);assert!(o.prepare_peer_round(&g,&server,"no-policy-bypass",data_for(&f,&g,&o,&server),&config(provider)).is_err());assert_eq!(grant(&f,&g),before);assert!(listener.accept().is_err());drop(a);
 }
}
fn ready(server:&crate::local_chat::Server,request:&str,alive:Arc<AtomicBool>)->(Fixture,Authority,Record,Arc<Owned>,Chat,PreparedCall,Arc<Approved>){
 let provider=server.id;let(f,a,g,o,main)=owned_at(server);
 let data=Arc::new(Captured::at(&f.path.join("goals"),&root(&f),DelegationInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),decision_id:o.lease().decision_id.clone()},server,&o.lease().model,crate::assistant_memory::now()).unwrap());
 let round=o.prepare_peer_round(&g,server,request,data,&config(provider)).unwrap();let review=round.review();let prepared=round.prepared;let url=server.url.clone();let key=server.key.clone();let observe:Observe=Arc::new(move||{if !alive.load(Ordering::Acquire){return Err(model::Error::Conflict);}Ok((config(provider),crate::local_chat::Server{id:provider,name:"Private exact DATA observer",url:url.clone(),key:key.clone()}))});
 let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let source=Source::capture_peer_data(o.clone(),&g,review.clone(),store,observe.clone()).unwrap();let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=Arc::new(review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap());(f,a,g,o,main,prepared,approved)
}
fn grant(f:&Fixture,g:&Record)->Value{serde_json::from_slice::<Value>(&std::fs::read(root(f).join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()).unwrap()["body"].clone()}
fn blocked()->String{json!({"kind":"blocked","reason":"Await independently verified child evidence; never self-certify criteria"}).to_string()}
#[test]fn approved_actual_body_is_journaled_before_http_then_sealed_with_original_turn_and_budget_on_both_local_protocols(){
 for provider in["ollama","lmstudio"]{let(mut server,http)=fixture(vec![("text/event-stream",stream(&blocked(),true))]);server.id=provider;let(f,a,g,o,_main,prepared,approved)=ready(&server,"reviewed-data-first",Arc::new(AtomicBool::new(true)));let body=prepared.request.body().clone();let consent=approved.reference().clone();assert_eq!(o.workers(),0);assert!(ledger(&f,&g).is_null());
  let(call,prepared)=o.consume_actual_call_with_peer_data(&g,"reviewed-data-first",prepared,Some(approved.clone()),crate::assistant_memory::now()).unwrap();assert!(ledger(&f,&g).is_null());let channel=call.reservation.channel();let result=run(crate::local_chat::send_runtime_prepared(None,&channel,prepared,&call)).unwrap();
  // The returned native reply still owns TurnLease; finish/record must remain
  // under this same logical turn, not infer approval from a dropped turn.
  assert_eq!(approved.bound_validity(crate::assistant_memory::now()),Validity::Current);call.finish(Some(result.accepted_output_bytes)).unwrap();call.record_result(&result.reply.text,result.accepted_output_bytes).unwrap();let requests=http.join().unwrap();assert_eq!(requests.len(),1);assert_eq!(requests[0].1,body);
  let stored=grant(&f,&g);assert_eq!(stored["schemaVersion"],39);assert_eq!(stored["planningUsage"]["schemaVersion"],2);assert_eq!(stored["planningUsage"]["rounds"][0]["peerData"],serde_json::to_value(&consent).unwrap());assert_eq!(stored["planningUsage"]["rounds"][0]["inputHash"],consent.input_hash);assert_eq!(stored["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert_eq!(stored["budgetUsage"]["attempts"][0]["phase"],"settled");
  drop(result);let row=&g.admissions[0];let reopened=Authority::existing(&root(&f)).unwrap();assert_eq!(approved.publication_validity(&reopened,&row.spec,row.proof.as_ref().unwrap(),"reviewed-data-first",crate::assistant_memory::now()),Validity::Current);assert!(matches!(crate::pet_runtime::results::lookup(&reopened,&row.spec,row.proof.as_ref().unwrap(),"reviewed-data-first").unwrap(),crate::pet_runtime::results::Lookup::Available{..}));
  let next=planning_journal::Request::capture(&g,&row.spec,o.lease(),"no-free-extra-round").unwrap();assert!(a.planning_context(&row.spec,row.proof.as_ref().unwrap(),o.lease(),next,crate::assistant_memory::now()).is_err());assert_eq!(grant(&f,&g),stored);assert!(!stored["nativeCompletion"].is_object());
 }
}
#[test]fn neither_data_dto_nor_prepared_metadata_can_bypass_the_original_native_approval_at_writer_handoff(){
 let server=crate::local_chat::Server{id:"ollama",name:"No network",url:"http://127.0.0.1:1".into(),key:None};let(f,_a,g,o,_main,prepared,approved)=ready(&server,"requires-native-data",Arc::new(AtomicBool::new(true)));let serialized=serde_json::to_value(approved.reference()).unwrap();assert!(serialized["inputHash"].is_string());assert!(o.consume_actual_call_with_peer_data(&g,"requires-native-data",prepared,None,crate::assistant_memory::now()).is_err());assert!(ledger(&f,&g).is_null());assert_eq!(o.workers(),0);
}
#[test]fn revocation_after_handoff_before_http_creates_no_attempt_or_request_and_cannot_be_reactivated(){
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let server=crate::local_chat::Server{id:"ollama",name:"No IO after revoke",url:format!("http://{}",listener.local_addr().unwrap()),key:None};let alive=Arc::new(AtomicBool::new(true));let(f,_a,g,o,_main,prepared,approved)=ready(&server,"revoke-before-native-http",alive.clone());let(call,prepared)=o.consume_actual_call_with_peer_data(&g,"revoke-before-native-http",prepared,Some(approved.clone()),crate::assistant_memory::now()).unwrap();alive.store(false,Ordering::Release);assert!(run(crate::local_chat::send_runtime_prepared(None,&call.reservation.channel(),prepared,&call)).is_err());assert!(listener.accept().is_err());assert!(ledger(&f,&g).is_null());alive.store(true,Ordering::Release);assert_eq!(approved.bound_validity(crate::assistant_memory::now()),Validity::Changed);drop(call);assert_eq!(o.workers(),0);
}
#[test]fn revocation_during_http_retains_full_unknown_charge_and_never_seals_a_success_or_replays(){
 let alive=Arc::new(AtomicBool::new(true));let revoke=alive.clone();let(server,http)=fixture_with_hook(vec![("text/event-stream",stream(&blocked(),true))],move|_|revoke.store(false,Ordering::Release));let(f,a,g,o,_main,prepared,approved)=ready(&server,"revoke-during-native-http",alive.clone());let(call,prepared)=o.consume_actual_call_with_peer_data(&g,"revoke-during-native-http",prepared,Some(approved.clone()),crate::assistant_memory::now()).unwrap();let result=run(crate::local_chat::send_runtime_prepared(None,&call.reservation.channel(),prepared,&call));assert!(result.is_err());assert!(call.dispatched.load(Ordering::Acquire));call.finish(None).unwrap();assert_eq!(http.join().unwrap().len(),1);let b=grant(&f,&g);assert_eq!(b["budgetUsage"]["attempts"][0]["phase"],"uncertain");assert!(b["budgetUsage"]["attempts"][0]["acceptedOutput"].is_null());assert!(b["budgetUsage"]["attempts"][0]["outputReserved"].as_u64().unwrap()>0);let row=&g.admissions[0];assert!(matches!(crate::pet_runtime::results::lookup(&a,&row.spec,row.proof.as_ref().unwrap(),"revoke-during-native-http").unwrap(),crate::pet_runtime::results::Lookup::RecoveryRequired{..}));alive.store(true,Ordering::Release);assert_eq!(approved.bound_validity(crate::assistant_memory::now()),Validity::Changed);assert_ne!(approved.publication_validity(&a,&row.spec,row.proof.as_ref().unwrap(),"revoke-during-native-http",crate::assistant_memory::now()),Validity::Current);assert_eq!(grant(&f,&g),b);
}
#[test]fn data_attempt_persistence_failure_before_or_after_publication_never_renews_budget_or_manufactures_a_dispatch(){
 for after in[false,true]{let server=crate::local_chat::Server{id:"ollama",name:"No dispatch in journal failure fixture",url:"http://127.0.0.1:1".into(),key:None};let(f,mut a,g,o,_main,prepared,approved)=ready(&server,"original-data-reservation",Arc::new(AtomicBool::new(true)));let(call,_prepared)=o.consume_actual_call_with_peer_data(&g,"original-data-reservation",prepared,Some(approved.clone()),crate::assistant_memory::now()).unwrap();let row=&g.admissions[0];let before=grant(&f,&g);let now=crate::assistant_memory::now();let attempt=Attempt{id:nonce().unwrap(),request_id:"original-data-reservation".into(),input_hash:approved.reference().input_hash.clone(),kind:Kind::Model,output_reserved:call.output_reserved,phase:crate::pet_runtime::effect_budget::Phase::Reserved,accepted_output:None,reserved_at:now,started_at:None,finished_at:None};a.fault=if after{Fault::AfterGrantPublish}else{Fault::BeforeGrantPublish};assert!(a.reserve_planning_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&attempt,call.planning.as_ref().unwrap(),now).is_err());let saved=grant(&f,&g);assert!(!call.dispatched.load(Ordering::Acquire));
  if after{assert_eq!(saved["planningUsage"]["rounds"].as_array().unwrap().len(),1);assert_eq!(saved["budgetUsage"]["attempts"][0]["phase"],"reserved");let fresh=Authority::existing(&root(&f)).unwrap();assert!(matches!(crate::pet_runtime::results::lookup(&fresh,&row.spec,row.proof.as_ref().unwrap(),"original-data-reservation").unwrap(),crate::pet_runtime::results::Lookup::RecoveryRequired{..}));let next=planning_journal::Request::capture(&g,&row.spec,o.lease(),"must-not-renew-after-lost-ack").unwrap();assert!(fresh.planning_context(&row.spec,row.proof.as_ref().unwrap(),o.lease(),next,crate::assistant_memory::now()).is_err());assert_eq!(grant(&f,&g),saved);}else{assert_eq!(saved,before);assert!(ledger(&f,&g).is_null());}
 }
}

fn data_for(f:&Fixture,g:&Record,o:&Owned,server:&crate::local_chat::Server)->Arc<Captured>{Arc::new(Captured::at(&f.path.join("goals"),&root(f),DelegationInput{pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),decision_id:o.lease().decision_id.clone()},server,&o.lease().model,crate::assistant_memory::now()).unwrap())}
fn model_metadata(provider:&str)->Value{if provider=="lmstudio"{json!({"models":[{"type":"llm","key":"fixture-free","publisher":"private-fixture","format":"gguf","size_bytes":1,"loaded_instances":[]}]})}else{local_metadata()}}
#[test]fn driver_facing_kernel_reviews_before_worker_then_checks_native_model_sends_exact_body_and_reconciles_one_original_round(){
 for provider in["ollama","lmstudio"]{let(mut server,http)=fixture(vec![("application/json",model_metadata(provider).to_string()),("text/event-stream",stream(&blocked(),true))]);server.id=provider;let(f,a,g,o,main)=owned_at(&server);let data=data_for(&f,&g,&o,&server);let round=o.prepare_peer_round(&g,&server,"opaque-native-data-round",data,&config(provider)).unwrap();assert_eq!(round.goal().revision,g.revision);let body=round.prepared.request.body().clone();assert_eq!(o.workers(),0);assert!(ledger(&f,&g).is_null());
  let url=server.url.clone();let observe:Observe=Arc::new(move||Ok((config(provider),crate::local_chat::Server{id:provider,name:"Native DATA exact synthetic destination",url:url.clone(),key:None})));let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let review=round.review();let source=Source::capture_peer_data(o.clone(),&g,review.clone(),store.clone(),observe.clone()).unwrap();o.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();let manual=main.runtime_resources().acquire(provider,Arc::default(),None).unwrap();drop(manual);let broker=crate::cli_chat::goal_decision_fixture(source.clone());broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let decision=broker.decision().unwrap();o.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();let approved=Arc::new(review.approve(decision,&o,&g,&observe,crate::assistant_memory::now()).unwrap());
  // A second real native DATA decision for the same body/turn is still not
  // the decision recorded by the writer. A result hash alone must not bless it.
  let other_review=DataReview::capture(&o,&g,round.prepared.peer_data.as_ref().unwrap().clone(),&round.prepared.request,crate::assistant_memory::now()).unwrap();let other_source=Source::capture_peer_data(o.clone(),&g,other_review.clone(),store.clone(),observe.clone()).unwrap();let other_broker=crate::cli_chat::goal_decision_fixture(other_source);other_broker.panel_answer(true,other_broker.request["goalTarget"].clone()).unwrap();let other=other_review.approve(other_broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap();assert_eq!(other.reference().input_hash,approved.reference().input_hash);assert_ne!(other.reference().id,approved.reference().id);
  let result=run(o.send_peer_round(None,round,approved.clone())).unwrap();assert!(matches!(result.body.outcome,crate::pet_runtime::planning_output::Outcome::Blocked{..}));let requests=http.join().unwrap();assert_eq!(requests.len(),2);assert_eq!(requests[0].0,if provider=="ollama"{"/api/show"}else{"/api/v1/models"});assert_eq!(requests[1].1,body);let saved=grant(&f,&g);assert_eq!(saved["schemaVersion"],39);assert_eq!(saved["planningUsage"]["rounds"].as_array().unwrap().len(),1);assert_eq!(saved["planningUsage"]["rounds"][0]["output"]["kind"],"blocked");assert_eq!(o.workers(),0);let row=&g.admissions[0];assert_eq!(approved.publication_validity(&a,&row.spec,row.proof.as_ref().unwrap(),"opaque-native-data-round",crate::assistant_memory::now()),Validity::Current);assert_eq!(other.publication_validity(&a,&row.spec,row.proof.as_ref().unwrap(),"opaque-native-data-round",crate::assistant_memory::now()),Validity::Changed);
  assert!(o.prepare_peer_round(&g,&server,"opaque-native-data-round",data_for(&f,&g,&o,&server),&config(provider)).is_err());assert!(o.prepare_peer_round(&g,&server,"another-logical-id-does-not-renew",data_for(&f,&g,&o,&server),&config(provider)).is_err());assert_eq!(grant(&f,&g),saved);
 }
}
#[test]fn revocation_during_explicit_native_metadata_check_prevents_model_io_and_budget_reservation(){
 let alive=Arc::new(AtomicBool::new(true));let revoke=alive.clone();let(server,http)=fixture_with_hook(vec![("application/json",local_metadata().to_string())],move|_|revoke.store(false,Ordering::Release));let(f,_a,g,o,_main)=owned_at(&server);let round=o.prepare_peer_round(&g,&server,"metadata-before-data-use",data_for(&f,&g,&o,&server),&config("ollama")).unwrap();let review=round.review();let url=server.url.clone();let observe:Observe=Arc::new(move||{if !alive.load(Ordering::Acquire){return Err(model::Error::Conflict);}Ok((config("ollama"),crate::local_chat::Server{id:"ollama",name:"Original native model",url:url.clone(),key:None}))});let source=Source::capture_peer_data(o.clone(),&g,review.clone(),Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap()),observe.clone()).unwrap();let broker=crate::cli_chat::goal_decision_fixture(source);broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let approved=Arc::new(review.approve(broker.decision().unwrap(),&o,&g,&observe,crate::assistant_memory::now()).unwrap());assert!(run(o.send_peer_round(None,round,approved)).is_err());let requests=http.join().unwrap();assert_eq!(requests.len(),1);assert_eq!(requests[0].0,"/api/show");assert!(ledger(&f,&g).is_null());assert_eq!(o.workers(),0);
}

fn own_plan_data(provider:&'static str)->(Fixture,Authority,Record,Arc<Owned>,Chat,Arc<Approved>,crate::pet_runtime::planning_output::Envelope){
 let deadline=crate::assistant_memory::now()+60_000;let raw=json!({"kind":"plan","description":"One exactly reviewed independent branch","steps":[{"description":"Delegate with own remaining pool","postcondition":"Only local receipt, never recipient success","operation":{"operationId":"pet.delegate","version":1,"arguments":{"toPetId":"integration_spotify","subgoal":"Literal bounded work, no source memory","criteria":["Independently verifiable result"],"allowance":{"modelCalls":1,"toolCalls":1,"outputBytes":8192},"expiresAt":deadline,"maxDepth":2}}}]}).to_string();
 let(mut server,http)=fixture(vec![("text/event-stream",stream(&raw,true))]);server.id=provider;let(f,a,g,o,main,prepared,approved)=ready(&server,"data-plan-for-own-publication",Arc::new(AtomicBool::new(true)));let(call,prepared)=o.consume_actual_call_with_peer_data(&g,"data-plan-for-own-publication",prepared,Some(approved.clone()),crate::assistant_memory::now()).unwrap();let result=run(crate::local_chat::send_runtime_prepared(None,&call.reservation.channel(),prepared,&call)).unwrap();call.finish(Some(result.accepted_output_bytes)).unwrap();call.record_result(&result.reply.text,result.accepted_output_bytes).unwrap();let row=&g.admissions[0];let output=crate::pet_runtime::planning_output::reconcile(&a,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&g,"data-plan-for-own-publication",crate::assistant_memory::now()).unwrap();assert!(matches!(output.body.outcome,crate::pet_runtime::planning_output::Outcome::Plan{..}));drop(result);drop(call);assert_eq!(http.join().unwrap().len(),1);(f,a,g,o,main,approved,output)
}
#[test]fn exact_own_publication_advances_data_scope_without_new_model_authority_and_new_own_reservations_are_not_old_sources(){
 for provider in["ollama","lmstudio"]{let(f,_a,g,o,_main,approved,_output)=own_plan_data(provider);let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let before=ledger(&f,&g);let prior=grant(&f,&g);assert!(o.publish_generated_plan(&store,"data-plan-for-own-publication",crate::assistant_memory::now()).is_err());assert_eq!(grant(&f,&g),prior);let scope=o.publish_peer_round_plan(store.clone(),"data-plan-for-own-publication",approved.clone()).unwrap();let published=scope.goal().clone();assert_ne!(published.revision,g.revision);assert_eq!(scope.current(),Validity::Current);assert_eq!(approved.bound_validity(crate::assistant_memory::now()),Validity::Changed);assert_eq!(scope.current(),Validity::Current);assert_eq!(ledger(&f,&g),before);
  let config=config(provider);let mut settings=crate::settings::Settings::default();settings.active_integrations=vec!["ai_ollama".into(),"ai_lmstudio".into(),"integration_spotify".into()];let batch=crate::pet_runtime::peer_plan_review::Batch::capture(&o,&published,&config,&settings,crate::assistant_memory::now()).unwrap().unwrap();let observe:crate::pet_runtime::peer_plan_review::Observe=Arc::new(move||Ok((config.clone(),settings.clone())));let source=Source::capture_peer(o.clone(),&published,batch.clone(),store.clone(),observe.clone()).unwrap();o.yield_for_decision(&store,&source,crate::assistant_memory::now()).unwrap();assert_eq!(scope.current(),Validity::Current);let manual=_main.runtime_resources().acquire(provider,Arc::default(),None).unwrap();drop(manual);let broker=crate::cli_chat::goal_decision_fixture(source.clone());broker.panel_answer(true,broker.request["goalTarget"].clone()).unwrap();let decision=broker.decision().unwrap();o.resume_after_decision(&store,&source,crate::assistant_memory::now()).unwrap();let choices=batch.approve(&decision,&o,&published,&observe,crate::assistant_memory::now()).unwrap();for choice in choices{o.send_message(&published,&choice,crate::assistant_memory::now(),||observe()).unwrap();}
  assert_eq!(grant(&f,&published)["delegationReservations"].as_array().unwrap().len(),1);assert_eq!(scope.current(),Validity::Current);let again=o.publish_peer_round_plan(store,"data-plan-for-own-publication",approved).unwrap();assert_eq!(again.goal().sequence,published.sequence);assert_eq!(again.current(),Validity::Current);assert_eq!(ledger(&f,&published)["attempts"].as_array().unwrap().iter().filter(|a|a["kind"]=="model").count(),1);
 }
}
#[test]fn parent_advance_rejects_external_changes_even_with_the_same_canonical_publication_reference(){
 let(f,a,g,o,_main,approved,_output)=own_plan_data("ollama");let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let scope=o.publish_peer_round_plan(store,"data-plan-for-own-publication",approved.clone()).unwrap();let target=scope.goal();let row=&g.admissions[0];let before=grant(&f,&g);
 for mode in["intent","revision","step"]{let mut forged=target.clone();match mode{"intent"=>forged.spec.intent="External change after the exact body review".into(),"revision"=>forged.revision=nonce().unwrap(),_=>forged.plans.last_mut().unwrap().steps[0].description="Changed outside the signed candidate".into()};assert!(crate::pet_runtime::peer_round_data::ParentAdvance::capture(&a,&row.spec,row.proof.as_ref().unwrap(),o.lease(),&g,&forged,approved.reference(),"data-plan-for-own-publication",false,crate::assistant_memory::now()).is_err(),"{mode}");}
 assert_eq!(scope.current(),Validity::Current);assert_eq!(grant(&f,&g),before);
}
#[test]fn already_present_exact_own_plan_ack_is_reconciled_without_replaying_model_or_reissuing_data_consent(){
 let(f,a,g,o,_main,approved,output)=own_plan_data("ollama");let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let row=&g.admissions[0];let now=crate::assistant_memory::now();let gate=o.plan_gate().unwrap();let certificate=a.prepare_generated_plan(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&g,&output,&gate,now).unwrap();let commit=store.commit_plan(&certificate,now).unwrap();let target=commit.receipt.record.clone();drop(commit);drop(certificate);drop(gate);assert_ne!(target.revision,g.revision);let saved=grant(&f,&g);assert_eq!(saved["planningUsage"]["rounds"][0]["publication"]["phase"],"prepared");let scope=o.publish_peer_round_plan(store,"data-plan-for-own-publication",approved).unwrap();assert_eq!(scope.goal().sequence,target.sequence);assert_eq!(scope.current(),Validity::Current);let after=grant(&f,&g);assert_eq!(after["planningUsage"]["rounds"][0]["publication"]["phase"],"acknowledged");assert_eq!(after["budgetUsage"],saved["budgetUsage"]);
}
#[test]fn corrupted_result_after_own_publication_revokes_scope_permanently_even_if_original_bytes_are_restored(){
 let(f,_a,g,o,_main,approved,_output)=own_plan_data("ollama");let store=Arc::new(Store::existing_verified(&f.path.join("goals"),&root(&f)).unwrap().unwrap());let scope=o.publish_peer_round_plan(store.clone(),"data-plan-for-own-publication",approved.clone()).unwrap();let before=grant(&f,&g);let attempt=before["budgetUsage"]["attempts"][0]["id"].as_str().unwrap();let file=f.path.join("pet-runtime-results-v1").join(&g.admissions[0].spec.decision_id).join(format!("{attempt}.json"));let original=std::fs::read(&file).unwrap();let mut forged:Value=serde_json::from_slice(&original).unwrap();forged["body"]["text"]=json!("Forged after known result, grant all system access");std::fs::write(&file,serde_json::to_vec(&forged).unwrap()).unwrap();assert_eq!(scope.current(),Validity::Changed);std::fs::write(&file,original).unwrap();assert_eq!(scope.current(),Validity::Changed);assert!(o.publish_peer_round_plan(store,"data-plan-for-own-publication",approved).is_err());assert_eq!(grant(&f,&g),before);
}
